"""Prepare a local-only directions page using confirmed project facts."""
from pathlib import Path
from bs4 import BeautifulSoup
import argparse
p=argparse.ArgumentParser();p.add_argument('--preview',type=Path,required=True);a=p.parse_args();repo=Path(__file__).resolve().parents[1]
out=a.preview/'site';out.mkdir(parents=True,exist_ok=True)
s=BeautifulSoup((repo/'contacts.html').read_text(encoding='utf-8'),'html.parser')
s.title.string='Как добраться — черновик на согласование'
for el in s.select('link[rel=canonical],meta[property^="og:"]'):el.decompose()
for el in s.select('[aria-current]'):del el['aria-current']
s.head.append(s.new_tag('meta',attrs={'name':'robots','content':'noindex,nofollow'}))
main=BeautifulSoup('''<main id="main"><section class="phead"><h1>Как добраться</h1><p>Ждём вас в студии «Музыка на кончиках пальцев»<br>в Сургуте, в ТЦ «Исток».</p></section>
<section class="route-card"><div><p class="route-label">Адрес студии</p><h2>ТЦ «Исток»</h2><p class="route-room">2 этаж · кабинет 202</p><p>Сургут, ул. 30 лет Победы, 58<br><span class="legend">Адрес указан на действующей странице контактов по карточке студии в 2ГИС.</span></p><a class="btn btn--dark" href="https://2gis.ru/surgut/geo/70000001084408756" target="_blank" rel="noopener">Открыть карту в 2ГИС ↗</a><p class="legend">В карточке выберите «Маршрут» и укажите, откуда едете.</p></div><div class="route-sign" aria-label="Второй этаж, кабинет 202"><span>этаж</span><b>02</b><hr><span>кабинет</span><strong>202</strong></div></section>
<section class="route-steps"><h2>До встречи у инструмента</h2><ol><li><span>01</span><h3>Найдите ТЦ «Исток»</h3><p>Постройте маршрут к студии в 2ГИС.</p></li><li><span>02</span><h3>Поднимитесь на второй этаж</h3><p>Студия находится на втором этаже торгового центра.</p></li><li><span>03</span><h3>Найдите кабинет 202</h3><p>Перед первым посещением согласуйте время занятия по телефону.</p></li></ol></section>
<section class="route-help"><h2>Нужна помощь на месте?</h2><p>Позвоните в студию, если не получается найти кабинет.</p><a class="btn btn--dark" href="tel:+79821493631">+7 (982) 149-36-31</a></section></main>''','html.parser')
s.main.replace_with(main)
banner=BeautifulSoup('<div class="route-preview">Черновик на согласование · <a href="../directions-review.html">Что проверить перед публикацией</a></div>','html.parser');s.body.insert(0,banner)
style=s.new_tag('style');style.string='''.route-preview{text-align:center;padding:14px;background:#e6ebd8;color:#27331d}.route-preview a{text-decoration:underline}.route-card{margin:0 40px 60px;padding:40px;border:1px solid #d7cdbd;border-radius:24px;display:grid;grid-template-columns:2fr 1fr;gap:40px;background:#fffdf8}.route-label{text-transform:uppercase;letter-spacing:.13em;font-size:12px}.route-card h2{font-size:44px;margin:16px 0}.route-room{font-size:24px}.route-sign{display:flex;flex-direction:column;justify-content:center;text-align:center;background:#e6eadb;border-radius:14px;padding:24px;color:#40502e}.route-sign b{font-size:80px;line-height:1.2}.route-sign strong{font-size:60px}.route-sign hr{width:65%;border:0;border-top:1px solid #a8b397}.route-steps,.route-help{padding:0 40px 60px}.route-steps ol{list-style:none;display:grid;grid-template-columns:repeat(3,1fr);gap:28px;padding:0}.route-steps li{border-top:1px solid #c6bba6;padding-top:22px}.route-steps li>span{font-size:30px;color:#74815c}.route-steps h3{font-size:24px}.route-help{max-width:800px}.route-help h2{font-size:34px}@media(max-width:700px){.route-card{grid-template-columns:1fr;margin:0 16px 36px;padding:24px;gap:24px}.route-card h2{font-size:34px}.route-sign{display:grid;grid-template-columns:1fr 1fr;align-items:center}.route-sign hr{display:none}.route-sign b,.route-sign strong{font-size:48px}.route-steps,.route-help{padding:0 24px 40px}.route-steps ol{grid-template-columns:1fr}.route-help h2{font-size:28px}}''';s.head.append(style)
(out/'directions.html').write_text(str(s),encoding='utf-8')
review='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Как добраться — согласование</title><style>body{max-width:850px;margin:40px auto;padding:24px;font:18px/1.65 system-ui;background:#f7f4ef;color:#292c25}a{color:#3e592d}li{margin:12px 0}.button{display:inline-block;padding:14px 22px;border-radius:30px;background:#27331d;color:white;text-decoration:none}</style><a href="index.html">← Все материалы</a><h1>Как добраться: на согласование</h1><p>Подготовлен текстовый маршрут с картой по ссылке, номером кабинета и телефоном. Основной сайт не изменён.</p><a class="button" href="site/directions.html">Посмотреть страницу</a><h2>Что найдено в материалах</h2><p>Просмотрено 51 уникальное исходное изображение из текущей папки проекта, папки «Пужалина» и прежней папки «Сайт пианаино». Есть занятия, концерты, награждения и интерьер. Подходящих фотографий входа в ТЦ, лестницы, коридора и двери 202 не найдено. Фото концертных площадок не считаются фотографиями пути к студии.</p><h2>Что подтвердить</h2><ul><li>Какой вход в ТЦ использовать: со стороны какой улицы или ориентира.</li><li>Как от входа пройти к лестнице или лифту и куда повернуть на втором этаже.</li><li>При необходимости — условия парковки и доступность с коляской. Сейчас таких обещаний на странице нет.</li></ul><h2>Какие кадры доснять</h2><ol><li>Фасад ТЦ с нужным входом.</li><li>Лестница или лифт от входа.</li><li>Коридор второго этажа с направлением к кабинету.</li><li>Дверь кабинета 202 с вывеской.</li></ol><p>Фотографии пока не добавлены. Сначала можно согласовать этот текстовый вариант; фото-маршрут останется отдельным дополнением. Адрес улицы взят с действующей страницы контактов, повторная проверка карточки 2ГИС инструментом сейчас недоступна.</p></html>'''
(a.preview/'directions-review.html').write_text(review,encoding='utf-8')
idx=a.preview/'index.html';t=idx.read_text(encoding='utf-8');link='<p><a class="btn primary" href="directions-review.html">Как добраться — новый раздел на согласование</a></p>'
if 'href="directions-review.html"' not in t:t=t.replace('<main>','<main>'+link,1)
idx.write_text(t,encoding='utf-8');print(out/'directions.html')
